class Solution:
    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        total_good = 0
        for k in range(n):
            first_half_sum = prefix[k + n // 2] - prefix[k]
            second_half_sum = prefix[n] - first_half_sum
            if first_half_sum > second_half_sum:
                total_good += 1
        return total_good

