class Solution:
    def countEquallySpaced(self, nums: list[int]) -> int:
        from collections import defaultdict

        count = defaultdict(list)
        for idx, num in enumerate(nums):
            count[num].append(idx)

        special = set()
        for num in count:
            indices = count[num]
            if len(indices) == 3:
                i1, i2, i3 = indices
                if (i2 - i1) == (i3 - i2):
                    special.add(num)

        return len(special)

class Solution:
    def kthDigit(self, k: int) -> int:
        if k <= 9:
            return k

        # Determine the block
        block = 1
        total_digits = 9
        while True:
            if block <= 99:
                digits_in_block = 20
            elif block <= 999:
                digits_in_block = 30
            elif block <= 9999:
                digits_in_block = 40
            else:
                digits_in_block = 50

            if total_digits + digits_in_block >= k:
                break
            total_digits += digits_in_block
            block += 1

        remaining = k - total_digits - 1
        start_num = 10 * block
        if block % 2 == 0:
            num = start_num + remaining
        else:
            num = start_num + 9 - remaining

        return num % 10

