class Solution:
    def lastVisitedCell(self, grid: list[list[str]]) -> list[int]:
        m = len(grid)
        if m == 0:
            return [0, 0]
        n = len(grid[0])

        visited = set()
        r, c = 0, 0
        visited.add((r, c))

        while True:
            current_char = grid[r][c]
            if current_char == 'L':
                nr, nc = r, c - 1
            elif current_char == 'R':
                nr, nc = r, c + 1
            elif current_char == 'U':
                nr, nc = r - 1, c
            elif current_char == 'D':
                nr, nc = r + 1, c

            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited:
                visited.add((nr, nc))
                r, c = nr, nc
            else:
                break

        return [r, c]
